export function wordSearch(board            , word        )          {
if(!word)return true;const rows=board.length,cols=board[0]?.length??0;const seen=new Set        ();function dfs(r       ,c       ,i       )        {if(i===word.length)return true;const key=r+","+c;if(r<0||c<0||r>=rows||c>=cols||seen.has(key)||board[r][c]!==word[i])return false;seen.add(key);const ok=dfs(r+1,c,i+1)||dfs(r-1,c,i+1)||dfs(r,c+1,i+1)||dfs(r,c-1,i+1);seen.delete(key);return ok;}for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)if(dfs(r,c,0))return true;return false;
}

